#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {   int nPhase;   int nLineOpenedHsNumber;   bool bHS;  } Queue_Drum;// Функция отображенияint PaintDrum(DefinePaint)  {  QueueP(Queue_Drum);  //  RECT rc = p->mRect;  bool bBadValue=false;  int nNumber=-1;  if (!p->bHS)  {    CShPolyHS* sh = (CShPolyHS*)PipeSh;	  if ( IsTypeOk )	  {        nNumber= sh->SP;        p->nPhase=nNumber;	  }  }  else  {    CShHS* sh = (CShHS*)PipeSh;	  if ( IsTypeOk )	  {      if (sh->mOn)        nNumber= 0;	  }  }  if (nNumber==-1)  {     if ( ::GetMnemoStyle() & MNEMO_EDIT )     {       COLORREF clr=0x80ff;       CMyPen pen( hDC, clr );			 pen.Rect( rc );     }  }  else  {    COLORREF clr=0;    //clr=0x80ff;    int nStartYLine1=p->mRect.top;    int nStartXLine1=p->mRect.left+8;    int nEndYLine1=p->mRect.top+31;    int nStartXLine2=p->mRect.left+22;    int nShiftY=0;    switch (p->nPhase)    {        case 1:nShiftY=60;break;        case 2:nShiftY=87;break;        case 3:nShiftY=156;break;        case 4:nShiftY=233;break;    }    nEndYLine1+=nShiftY;    CMyPen pen( hDC, clr);    pen.Vert(nStartXLine1,nStartYLine1,nEndYLine1);    pen.Vert(nStartXLine2,nStartYLine1,nEndYLine1);    CMyPen pen2( hDC, clr, 2 );    CMyBrush brush( hDC, 0xc0c0c0,true );    RECT rcRound;    rcRound.left=nStartXLine1;    rcRound.right=nStartXLine1+14;    rcRound.top=nEndYLine1-7;    rcRound.bottom=nEndYLine1+7;    pen2.Ellipse(rcRound);    CMyPen penBlackLine( hDC, clr);    int nKrest1X=rcRound.left+3;    int nKrest1Y=rcRound.top+3;    int nKrest2X=rcRound.right-3;    int nKrest2Y=rcRound.bottom-3;    ::MoveToEx( hDC, nKrest1X, nKrest1Y, NULL );    ::LineTo  ( hDC, nKrest2X, nKrest2Y );    ::MoveToEx( hDC, nKrest1X, nKrest2Y, NULL );    ::LineTo  ( hDC, nKrest2X, nKrest1Y );    RECT rcRectFirst;    rcRectFirst.top=rcRound.bottom+1;    rcRectFirst.bottom=rcRectFirst.top+9;    rcRectFirst.left=rcRound.left-7;    rcRectFirst.right=rcRectFirst.left+29;    COLORREF clrRect=0x808080;    if (p->nPhase>2)      clrRect=0x00ff00;    CMyBrush brushRect( hDC, clrRect,true );    brushRect.Rect(rcRectFirst);    penBlackLine.Rect(rcRectFirst);    RECT rcRectSecond;    rcRectSecond.top=rcRectFirst.bottom;    rcRectSecond.left=rcRectFirst.left+11;    rcRectSecond.right=rcRectSecond.left+6;    rcRectSecond.bottom=rcRectSecond.top+179;    brushRect.Rect(rcRectSecond);    penBlackLine.Rect(rcRectSecond);    POINT p0Array[]= {    {rcRectSecond.left-4,rcRectSecond.bottom},    {rcRectSecond.right+5,rcRectSecond.bottom},    {rcRectSecond.right+2,rcRectSecond.bottom+11},    {rcRectSecond.left,rcRectSecond.bottom+11},     };     brushRect.Points(p0Array,4,1);     COLORREF clrLine=0x808080;     CShKlapan* sh2 = (CShKlapan*)(q.m_pPipe->Sh(p->nLineOpenedHsNumber));     if ( sh2->RetCode==CShBase::rcOK )	   {          if ( sh2->Vent>=100 )            clrLine=0xff0000;	   }     int nBeginYLine=rcRectFirst.top+4;     int nBeginXLine=rcRectFirst.right+1;     int nEndXLine=nBeginXLine+28;     RECT rcFullEllipse;     rcFullEllipse.top=nBeginYLine;     int nRadius=13;     rcFullEllipse.left=nEndXLine-nRadius;     rcFullEllipse.right=rcFullEllipse.left+2*nRadius;     rcFullEllipse.bottom=rcFullEllipse.top+2*nRadius;     RECT rcSmallEllipse=rcFullEllipse;     rcSmallEllipse.left=rcFullEllipse.left+nRadius;     rcSmallEllipse.bottom=rcSmallEllipse.top+nRadius;     penBlackLine.Horz(rcSmallEllipse.bottom+1,rcSmallEllipse.right-5,rcSmallEllipse.right+5);     penBlackLine.Horz(rcSmallEllipse.bottom+4,rcSmallEllipse.right-5,rcSmallEllipse.right+5);     CMyPen penLine( hDC, clrLine,3);     penLine.Horz(nBeginYLine,nBeginXLine,nEndXLine);     ::Arc( hDC, rcFullEllipse.left, rcFullEllipse.top, rcFullEllipse.right, rcFullEllipse.bottom,                rcSmallEllipse.right, rcSmallEllipse.bottom,rcSmallEllipse.left, rcSmallEllipse.top  );     nBeginXLine=rcSmallEllipse.right;     nBeginYLine=rcSmallEllipse.bottom+5;     int nEndYLine=nBeginYLine+197-nShiftY;     if (p->nPhase==4)          nEndYLine=nBeginYLine;     else        penLine.Vert(nBeginXLine,nBeginYLine,nEndYLine);     nRadius=25;     rcFullEllipse.top=nEndYLine-nRadius;     rcFullEllipse.left=nBeginXLine;     rcFullEllipse.right=rcFullEllipse.left+2*nRadius;     rcFullEllipse.bottom=rcFullEllipse.top+2*nRadius;     rcSmallEllipse=rcFullEllipse;     rcSmallEllipse.top=rcFullEllipse.top+nRadius;     rcSmallEllipse.bottom=rcSmallEllipse.top;    ::Arc( hDC, rcFullEllipse.left, rcFullEllipse.top, rcFullEllipse.right, rcFullEllipse.bottom,           rcSmallEllipse.left, rcSmallEllipse.bottom,rcSmallEllipse.right, rcSmallEllipse.top  );    if (p->nPhase==4)    {      penLine.Vert(rcFullEllipse.right,rcSmallEllipse.top-36,rcSmallEllipse.top);      rcSmallEllipse.top=rcSmallEllipse.top-36;    }    nRadius=13;    rcFullEllipse.top=rcSmallEllipse.top-nRadius;    rcFullEllipse.left=rcFullEllipse.right;    rcFullEllipse.right=rcFullEllipse.left+2*nRadius;     rcFullEllipse.bottom=rcFullEllipse.top+2*nRadius;     rcSmallEllipse=rcFullEllipse;     rcSmallEllipse.top=rcFullEllipse.top+nRadius;     rcSmallEllipse.bottom=rcSmallEllipse.top;    ::Arc( hDC, rcFullEllipse.left, rcFullEllipse.top, rcFullEllipse.right, rcFullEllipse.bottom,           rcSmallEllipse.right, rcSmallEllipse.bottom,rcSmallEllipse.left, rcSmallEllipse.top  );  }  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddDrum(DefineTegs)  {  //  AddQueueEx(Queue_Drum);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintDrum;  p->nPhase=0;  p->bHS=false;  //  //  p->nNumber=-1;  char szHsName[64]="";  char szPHSName[64]="";  char szKlapanOpen[64]="";  p->nLineOpenedHsNumber=-1;  //  STegObj obj[] =    {	  { 'S', "phsName", szPHSName, 63 },    { 'S', "hsName", szHsName, 63 },    { 'S', "klapanOpen", szKlapanOpen, 63 },    { 'I', "phase", &p->nPhase },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsName)  {	  p->nNumber=def.AddKind( id_HS    , szHsName );    p->bHS=true;  }  else  if (*szPHSName)	  p->nNumber=def.AddKind( id_PHS    , szPHSName );  if (*szKlapanOpen)	  p->nLineOpenedHsNumber=def.AddKind( id_Klapan    , szKlapanOpen);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~